enum class Color : char {
    Black = '0',
    DarkBlue = '1',
    DarkGreen = '2',
    DarkAqua = '3',
    DarkRed = '4',
    DarkPurple = '5',
    Gold = '6',
    Gray = '7',
    DarkGray = '8',
    Blue = '9',
    Green = 'a',
    Aqua = 'b',
    Red = 'c',
    LightPurple = 'd',
    Yellow = 'e',
    White = 'f',
};

enum class Style : char {
    Obfuscated = 'k',
    Bold = 'l',
    Strikethrough = 'm',
    Underlined = 'n',
    Italic = 'o',
};

// The order a span's style codes are written in.
inline constexpr Style styles_in_order[] = {Style::Obfuscated, Style::Bold, Style::Strikethrough, Style::Underlined, Style::Italic};

// Text in one color and set of styles, borrowing its text: tuff::gold("hi").bold().
class Span {
  public:
    Span(const char *text) : text_(raw::tuff_str(text)) {}
    Span(Str text) : text_(text) {}
    // Anything with a view(), such as Text and String.
    template <class T> Span(const T &text) : text_(text.view()) {}

    Span color(Color c) const {
        Span s = *this;
        s.color_ = static_cast<char>(c);
        return s;
    }
    Span style(Style st) const {
        Span s = *this;
        s.styles_ |= bit(st);
        return s;
    }
    Span black() const { return color(Color::Black); }
    Span dark_blue() const { return color(Color::DarkBlue); }
    Span dark_green() const { return color(Color::DarkGreen); }
    Span dark_aqua() const { return color(Color::DarkAqua); }
    Span dark_red() const { return color(Color::DarkRed); }
    Span dark_purple() const { return color(Color::DarkPurple); }
    Span gold() const { return color(Color::Gold); }
    Span gray() const { return color(Color::Gray); }
    Span dark_gray() const { return color(Color::DarkGray); }
    Span blue() const { return color(Color::Blue); }
    Span green() const { return color(Color::Green); }
    Span aqua() const { return color(Color::Aqua); }
    Span red() const { return color(Color::Red); }
    Span light_purple() const { return color(Color::LightPurple); }
    Span yellow() const { return color(Color::Yellow); }
    Span white() const { return color(Color::White); }
    Span obfuscated() const { return style(Style::Obfuscated); }
    Span bold() const { return style(Style::Bold); }
    Span strikethrough() const { return style(Style::Strikethrough); }
    Span underlined() const { return style(Style::Underlined); }
    Span italic() const { return style(Style::Italic); }

    Str text() const { return text_; }
    // The color code, 0 for none.
    char color_code() const { return color_; }
    bool has(Style st) const { return (styles_ & bit(st)) != 0; }

  private:
    static uint8_t bit(Style st) {
        for (unsigned i = 0; i < sizeof styles_in_order; i++) {
            if (styles_in_order[i] == st) {
                return static_cast<uint8_t>(1u << i);
            }
        }
        return 0;
    }

    Str text_;
    char color_ = 0;
    uint8_t styles_ = 0;
};

